import type { RouteRecordRaw } from 'vue-router';
import type { ModuleFrontendContribution } from '@peanut-admin/vue';
// The module is generated by the Vite plugin in vite.config.ts.
// eslint-disable-next-line import/no-unresolved
import lockedContributions from 'virtual:peanut-module-contributions';

// eslint-disable-next-line import/prefer-default-export
export const moduleRoutes: RouteRecordRaw[] = (
  lockedContributions as ModuleFrontendContribution[]
)
  .flatMap((contribution) => contribution.routes)
  .map(
    (route): RouteRecordRaw =>
      ({
        ...route,
        meta: {
          ...route.meta,
          hideInMenu: true,
        },
      } as RouteRecordRaw)
  );
